import gurobipy as gp
from gurobipy import GRB
capacity_records = [r for r in LEGACY_RECORDS if r['source'].endswith('capacity.csv')]
product_records = [r for r in LEGACY_RECORDS if r['source'].endswith('products.csv')]
shelf_ids = []
shelf_capacities = {}
for rec in capacity_records:
    shelf_id = rec['values']['ShelfID']
    shelf_ids.append(shelf_id)
    shelf_capacities[shelf_id] = float(rec['values']['Capacity'])
product_names = []
product_values = {}
product_weights = {}
for rec in product_records:
    pname = rec['values']['ProductName']
    product_names.append(pname)
    product_values[pname] = float(rec['values']['Value'])
    product_weights[pname] = float(rec['values']['Weight'])
m = gp.Model('retail_shelf_allocation')
x_vars = m.addVars(shelf_ids, product_names, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((product_values[product_name] * x_vars[shelf_id, product_name] for shelf_id in shelf_ids for product_name in product_names)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((product_weights[product_name] * x_vars[shelf_id, product_name] for product_name in product_names)) <= shelf_capacities[shelf_id] for shelf_id in shelf_ids), name='')
first_product = product_names[0]
m.addConstr(gp.quicksum((x_vars[shelf_id, first_product] for shelf_id in shelf_ids)) >= 5, name='min_smartphone')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')
